<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap(); $tujuhHariLalu = now()->subDays(6)->startOfDay(); $chartRaw = App\Models\DetailPresensi::select(Illuminate\Support\Facades\DB::raw("DATE(presensis.tanggal) as tgl"), "detail_presensis.status_kehadiran")->join("presensis", "presensis.id", "=", "detail_presensis.presensi_id")->where("presensis.tanggal", ">=", $tujuhHariLalu)->get(); print_r($chartRaw->groupBy("tgl")->toArray());
